      // Debug function to list all scenarios to the console
      function listAllData() {
        scenarios.forEach((data, index) => {
          console.log(`Scenario ${index}:`, data);
        });
      }
      listAllData();

      let scene, camera, renderer, composer, controls;
      let targetLayersGroup, cratersGroup, airGroup, rulerGroup;
      let projectile, shockwave, explosionSphere, boomRing, machCone, airBox;
      let currentData = scenarios[0];
      let activeCrater = null;
      let dustParticles;
      let ambientDustParticles;

      let animState = "IDLE";
      let clock = new THREE.Clock();
      let simTime = 0;
      let prevFrame = null;
      let followCam = false;
      let simSpeedMultiplier = 1.0;
      let explosionTriggered = false;
      let cameraShake = 0;
      let boomRingGrowthRate = 15.0; // physics-derived from Mach number at the boom instant

      // Telemetry Graph
      let telemetryChart;
