      let chartDataVel = [];

      function init() {
        const container = document.getElementById("canvas-container");
        scene = new THREE.Scene();
        scene.background = new THREE.Color(0x05080f);
        scene.fog = new THREE.Fog(0x05080f, 300, 200000); // Linear fog pushed far back to prevent obscuring zoom

        camera = new THREE.PerspectiveCamera(
          50,
          window.innerWidth / window.innerHeight,
          0.1,
          200000,
        );
        camera.position.set(45, 30, 60);

        renderer = new THREE.WebGLRenderer({
          antialias: false,
          powerPreference: "high-performance",
        });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap; // Soft shadows
        renderer.physicallyCorrectLights = true;
        container.appendChild(renderer.domElement);

        // Post Processing Bloom
        const renderScene = new THREE.RenderPass(scene, camera);
        const bloomPass = new THREE.UnrealBloomPass(
          new THREE.Vector2(window.innerWidth, window.innerHeight),
          1.5,
          0.4,
          0.85,
        );
        bloomPass.threshold = 0.2;
        bloomPass.strength = 1.2; // Glowing effect
        bloomPass.radius = 0.5;

        composer = new THREE.EffectComposer(renderer);
        composer.addPass(renderScene);
        composer.addPass(bloomPass);

        controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.target.set(0, -15, 0);
        controls.maxPolarAngle = Math.PI / 2 + 0.1; // Restrict underground camera flip
        controls.minDistance = 5;
        controls.maxDistance = 350;

        setupLighting();
        setupEnvironment();

        targetLayersGroup = new THREE.Group();
        scene.add(targetLayersGroup);
        cratersGroup = new THREE.Group();
        scene.add(cratersGroup);
        rulerGroup = new THREE.Group();
        scene.add(rulerGroup);

        setupProjectile();
        setupEffects();

        initECharts();

        window.addEventListener("resize", onWindowResize);
        if (scenarios.length > 0) {
          selectScenario(0);
        }
        animate(0);
      }

      function setupLighting() {
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6); // Increased base light
        scene.add(ambientLight);

        const hemiLight = new THREE.HemisphereLight(0x0f172a, 0x0f172a, 0.4); // Sky color, ground color
        scene.add(hemiLight);

        const dirLight = new THREE.DirectionalLight(0xfff0dd, 2.5); // Warmer, brighter sun
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 500;
        const d = 80;
        dirLight.shadow.camera.left = -d;
        dirLight.shadow.camera.right = d;
        dirLight.shadow.camera.top = d;
        dirLight.shadow.camera.bottom = -d;
        scene.add(dirLight);

        const fillLight = new THREE.PointLight(0x38bdf8, 1.0, 100); // Cool fill light
        fillLight.position.set(-30, 20, -30);
        scene.add(fillLight);
      }

      function createTextSprite(message, color) {
        const canvas = document.createElement("canvas");
        const context = canvas.getContext("2d");
        canvas.width = 256;
        canvas.height = 128;
        context.font = "Bold 36px 'JetBrains Mono', monospace";
        context.fillStyle = color;
        context.fillText(message, 10, 50);
        const texture = new THREE.CanvasTexture(canvas);
        const spriteMaterial = new THREE.SpriteMaterial({
          map: texture,
          transparent: true,
        });
        const sprite = new THREE.Sprite(spriteMaterial);
        sprite.scale.set(20, 10, 1);
        return sprite;
      }

      function setupEnvironment() {
        // Ground Grid with glow
        const gridHelper = new THREE.GridHelper(200000, 10000, 0x0ea5e9, 0x1e293b);
        gridHelper.position.y = 0.1;
        scene.add(gridHelper);

        // Ground Zero Decal removed per user request

        // Volumetric Air Box Container
        airGroup = new THREE.Group();
        scene.add(airGroup);
      }

      function rebuildRulers(maxAlt) {
        while (rulerGroup.children.length > 0)
          rulerGroup.remove(rulerGroup.children[0]);

        // 1. Underground Depth Ruler (0m to 150m with 1m/5m/10m school ruler sub-divisions)
        const depthLine = new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(14, 0, 14),
            new THREE.Vector3(14, -150, 14),
          ]),
          new THREE.LineBasicMaterial({
            color: 0x38bdf8,
            transparent: true,
            opacity: 0.6,
          }),
        );
        rulerGroup.add(depthLine);

        for (let depthY = 0; depthY <= 150; depthY++) {
          let tickLen = 0.8; // 1m minor tick
          let tickRadius = 0.08;
          let isMajor = depthY % 10 === 0;
          let isMedium = depthY % 5 === 0 && !isMajor;

          if (isMajor) {
            tickLen = 3.5;
            tickRadius = 0.2;
          } else if (isMedium) {
            tickLen = 2.0;
            tickRadius = 0.12;
          }

          let tColor = 0x38bdf8;
          if (depthY > 30) tColor = 0xfacc15;
          if (depthY > 80) tColor = 0xf87171;

          const tickGeom = new THREE.CylinderGeometry(
            tickRadius,
            tickRadius,
            tickLen,
          );
          tickGeom.rotateZ(Math.PI / 2);
          const tMat = new THREE.MeshBasicMaterial({ color: tColor });
          const tick = new THREE.Mesh(tickGeom, tMat);

          tick.position.set(14 + tickLen / 2, -depthY, 14);
          rulerGroup.add(tick);

          if (isMajor) {
            const sprite = createTextSprite(
              depthY + "m",
              "#" + tColor.toString(16).padStart(6, "0"),
            );
            sprite.position.set(14 + tickLen + 3.0, -depthY, 14);
            rulerGroup.add(sprite);
          }
        }

        // 2. Air Altitude Ruler (0m to altLimit with 1m/5m/10m school ruler sub-divisions)
        let altLimit = Math.max(
          50,
          Math.ceil((maxAlt > 0 ? maxAlt : 50) / 10) * 10,
        );
        const airLine = new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(-15, 0, -15),
            new THREE.Vector3(-15, altLimit, -15),
          ]),
          new THREE.LineBasicMaterial({
            color: 0x0ea5e9,
            transparent: true,
            opacity: 0.6,
          }),
        );
        rulerGroup.add(airLine);

        for (let altY = 0; altY <= altLimit; altY++) {
          let tickLen = 0.8; // 1m minor tick
          let tickRadius = 0.08;
          let isMajor = altY % 10 === 0;
          let isMedium = altY % 5 === 0 && !isMajor;

          if (isMajor) {
            tickLen = 3.5;
            tickRadius = 0.2;
          } else if (isMedium) {
            tickLen = 2.0;
            tickRadius = 0.12;
          }

          const tickGeom = new THREE.CylinderGeometry(
            tickRadius,
            tickRadius,
            tickLen,
          );
          tickGeom.rotateZ(Math.PI / 2);
          const tMat = new THREE.MeshBasicMaterial({ color: 0x0ea5e9 });
          const tick = new THREE.Mesh(tickGeom, tMat);

          tick.position.set(-15 - tickLen / 2, altY, -15);
          rulerGroup.add(tick);

          if (isMajor && altY > 0) {
            const sprite = createTextSprite(altY + "m", "#0ea5e9");
            sprite.position.set(-15 - tickLen - 3.0, altY, -15);
            rulerGroup.add(sprite);
          }
        }
      }

      // USA National Anthem (The Star-Spangled Banner) Web Audio Synthesizer
      let audioCtx = null;
      let anthemNodes = [];

      // Resume audio context on first user interaction if suspended
      ["click", "keydown", "pointerdown"].forEach((evt) => {
        window.addEventListener(
          evt,
          () => {
            if (audioCtx && audioCtx.state === "suspended") {
              audioCtx.resume().catch(() => {});
            }
          },
          { passive: true },
        );
      });

      function playAnthem() {
        stopAnthem();
        try {
          if (navigator.userActivation && !navigator.userActivation.hasBeenActive) {
            console.warn("AudioContext requires user gesture. Anthem playback skipped.");
            return;
          }
          audioCtx = new (window.AudioContext || window.webkitAudioContext)();
          if (audioCtx.state === "suspended") {
            audioCtx.resume().catch(() => {});
          }

          // Star-Spangled Banner Anthem Notes (Frequency in Hz, Duration in Seconds)
          const notes = [
            { f: 392.0, d: 0.35 }, // G4 (Oh)
            { f: 329.63, d: 0.35 }, // E4 (say)
            { f: 261.63, d: 0.6 }, // C4 (can)
            { f: 329.63, d: 0.6 }, // E4 (you)
            { f: 392.0, d: 0.6 }, // G4 (see)
            { f: 523.25, d: 1.1 }, // C5 (by)

            { f: 659.25, d: 0.7 }, // E5 (the)
            { f: 587.33, d: 0.35 }, // D5 (dawn's)
            { f: 523.25, d: 0.6 }, // C5 (ear-)
            { f: 329.63, d: 0.6 }, // E4 (ly)
            { f: 370.0, d: 0.6 }, // F#4 (light)
            { f: 392.0, d: 1.1 }, // G4 (what)

            { f: 392.0, d: 0.35 }, // G4 (so)
            { f: 392.0, d: 0.35 }, // G4 (proud-)
            { f: 659.25, d: 0.7 }, // E5 (ly)
            { f: 587.33, d: 0.35 }, // D5 (we)
            { f: 523.25, d: 0.6 }, // C5 (hailed)
            { f: 493.88, d: 0.6 }, // B4 (at)
            { f: 440.0, d: 0.6 }, // A4 (the)
            { f: 493.88, d: 0.6 }, // B4 (twilight's)
            { f: 523.25, d: 1.2 }, // C5 (last)

            { f: 523.25, d: 0.35 }, // C5 (gleaming?)
            { f: 523.25, d: 0.35 }, // C5 (Whose)
            { f: 659.25, d: 0.6 }, // E5 (broad)
            { f: 698.46, d: 0.6 }, // F5 (stripes)
            { f: 783.99, d: 1.0 }, // G5 (and)
            { f: 783.99, d: 0.6 }, // G5 (bright)
            { f: 659.25, d: 0.35 }, // E5 (stars)
            { f: 587.33, d: 0.6 }, // D5 (through)
            { f: 523.25, d: 0.6 }, // C5 (the)
            { f: 587.33, d: 1.2 }, // D5 (perilous)

            { f: 659.25, d: 0.6 }, // E5 (fight)
            { f: 659.25, d: 0.35 }, // E5 (O'er)
            { f: 587.33, d: 0.35 }, // D5 (the)
            { f: 523.25, d: 0.6 }, // C5 (ramparts)
            { f: 493.88, d: 0.6 }, // B4 (we)
            { f: 440.0, d: 0.6 }, // A4 (watched)
            { f: 493.88, d: 0.6 }, // B4 (were)
            { f: 523.25, d: 1.4 }, // C5 (so)

            { f: 523.25, d: 0.35 }, // C5 (gal-)
            { f: 523.25, d: 0.35 }, // C5 (lant-)
            { f: 392.0, d: 0.6 }, // G4 (ly)
            { f: 329.63, d: 0.6 }, // E4 (stream-)
            { f: 392.0, d: 0.6 }, // G4 (ing?)
            { f: 523.25, d: 1.4 }, // C5 (!!!)
          ];

          let currentTime = audioCtx.currentTime + 0.05;
          const masterGain = audioCtx.createGain();
          masterGain.gain.setValueAtTime(0.18, currentTime);
          masterGain.connect(audioCtx.destination);
          anthemNodes.push(masterGain);

          notes.forEach((n) => {
            const osc = audioCtx.createOscillator();
            const noteGain = audioCtx.createGain();

            // Sawtooth + Brass timbre
            osc.type = "sawtooth";
            osc.frequency.setValueAtTime(n.f, currentTime);

            noteGain.gain.setValueAtTime(0.001, currentTime);
            noteGain.gain.linearRampToValueAtTime(0.2, currentTime + 0.04);
            noteGain.gain.exponentialRampToValueAtTime(
              0.001,
              currentTime + n.d * 0.95,
            );

            osc.connect(noteGain);
            noteGain.connect(masterGain);

            osc.start(currentTime);
            osc.stop(currentTime + n.d);

            anthemNodes.push(osc);
            anthemNodes.push(noteGain);

            currentTime += n.d;
          });
        } catch (e) {
          console.log("AudioContext initialized on user gesture:", e);
        }
      }

      function stopAnthem() {
        anthemNodes.forEach((node) => {
          try {
            if (node.stop) node.stop();
            if (node.disconnect) node.disconnect();
          } catch (e) {}
        });
        anthemNodes = [];
        if (audioCtx && audioCtx.state !== "closed") {
          try {
            audioCtx.close();
          } catch (e) {}
        }
      }

      function computePlanckBlackbodyColor(tempKelvin, baseColorHex) {
        // Converts Temperature (Kelvin) to Planck blackbody radiation RGB emission
        // < 500 K: Base metal finish
        // 500 K - 900 K: Incipient red heat (0x7f1d1d to 0xd97706)
        // 900 K - 1500 K: Cherry red to bright orange (0xf97316)
        // 1500 K - 2200 K: Incandescent yellow-white (0xfffbeb)
        // > 2200 K: Radiant plasma white-blue (0xe0f2fe)
        const baseColor = new THREE.Color(baseColorHex);
        const radColor = new THREE.Color();

        if (tempKelvin < 500) {
          radColor.copy(baseColor);
        } else if (tempKelvin < 900) {
          const t = (tempKelvin - 500) / 400;
          radColor.lerpColors(baseColor, new THREE.Color(0xd97706), t);
        } else if (tempKelvin < 1500) {
          const t = (tempKelvin - 900) / 600;
          radColor.lerpColors(
            new THREE.Color(0xd97706),
            new THREE.Color(0xf97316),
            t,
          );
        } else if (tempKelvin < 2200) {
          const t = (tempKelvin - 1500) / 700;
          radColor.lerpColors(
            new THREE.Color(0xf97316),
            new THREE.Color(0xfffbeb),
            t,
          );
        } else {
          const t = Math.min(1.0, (tempKelvin - 2200) / 1000);
          radColor.lerpColors(
            new THREE.Color(0xfffbeb),
            new THREE.Color(0xe0f2fe),
            t,
          );
        }
        return radColor;
      }

      function mergeGeometriesSimple(geometries) {
        let totalVerts = 0;
        const nonIndexed = geometries.map((g) =>
          g.index ? g.toNonIndexed() : g,
        );
        nonIndexed.forEach((g) => {
          totalVerts += g.attributes.position.count;
        });

        const positions = new Float32Array(totalVerts * 3);
        const normals = new Float32Array(totalVerts * 3);
        const uvs = new Float32Array(totalVerts * 2);

        let offsetPos = 0;
        let offsetUv = 0;

        nonIndexed.forEach((g) => {
          const p = g.attributes.position.array;
          positions.set(p, offsetPos);

          if (g.attributes.normal) {
            normals.set(g.attributes.normal.array, offsetPos);
          }
          if (g.attributes.uv) {
            uvs.set(g.attributes.uv.array, offsetUv);
          }

          offsetPos += p.length;
          if (g.attributes.uv) offsetUv += g.attributes.uv.array.length;
        });

        const merged = new THREE.BufferGeometry();
        merged.setAttribute(
          "position",
          new THREE.BufferAttribute(positions, 3),
        );
        merged.setAttribute("normal", new THREE.BufferAttribute(normals, 3));
        merged.setAttribute("uv", new THREE.BufferAttribute(uvs, 2));
        merged.computeVertexNormals();
        return merged;
      }

      function createGBU57Geometry(pRadius, pLength) {
        const points = [];
        const noseLen = pLength * 0.25;
        const bodyLen = pLength * 0.55;
        const tailLen = pLength * 0.2;

        const halfLen = pLength / 2;
        const yNose = -halfLen;
        const yBodyStart = yNose + noseLen;
        const yBodyEnd = yBodyStart + bodyLen;
        const yTailEnd = halfLen;

        // 1. Ogive nose curve (pointing down along -Y)
        points.push(new THREE.Vector2(0, yNose));
        const noseSteps = 12;
        for (let i = 1; i <= noseSteps; i++) {
          const t = i / noseSteps;
          const r = pRadius * Math.sin(t * Math.PI * 0.5);
          const y = yNose + t * noseLen;
          points.push(new THREE.Vector2(r, y));
        }

        // 2. Main cylinder body with structural reinforcement ring
        points.push(new THREE.Vector2(pRadius, yBodyStart));
        points.push(new THREE.Vector2(pRadius, yBodyEnd * 0.5));
        points.push(new THREE.Vector2(pRadius * 1.03, yBodyEnd * 0.52));
        points.push(new THREE.Vector2(pRadius * 1.03, yBodyEnd * 0.55));
        points.push(new THREE.Vector2(pRadius, yBodyEnd * 0.57));
        points.push(new THREE.Vector2(pRadius, yBodyEnd));

        // 3. Boat-tail tapered tail cone
        points.push(new THREE.Vector2(pRadius * 0.7, yTailEnd - tailLen * 0.2));
        points.push(new THREE.Vector2(pRadius * 0.5, yTailEnd));
        points.push(new THREE.Vector2(0, yTailEnd));

        const bodyGeom = new THREE.LatheGeometry(points, 32);
        const geometries = [bodyGeom];

        // 4. Tail Fins (4 Grid/Planar Fins at 90-degree intervals)
        const finW = pRadius * 1.8;
        const finH = tailLen * 0.8;
        const finT = pRadius * 0.12;

        for (let a = 0; a < 4; a++) {
          const angle = (a * Math.PI) / 2;
          const finGeom = new THREE.BoxGeometry(finT, finH, finW);
          const posX = Math.cos(angle) * (pRadius * 0.5 + finW / 2);
          const posZ = Math.sin(angle) * (pRadius * 0.5 + finW / 2);
          const posY = yBodyEnd + finH * 0.3;

          finGeom.rotateY(-angle);
          finGeom.translate(posX, posY, posZ);
          geometries.push(finGeom);
        }

        // 5. Longitudinal Body Strakes (4 guiding ribs around mid body)
        const strakeT = pRadius * 0.12;
        const strakeH = bodyLen * 0.5;
        const strakeW = pRadius * 0.25;

        for (let a = 0; a < 4; a++) {
          const angle = (a * Math.PI) / 2 + Math.PI / 4;
          const strakeGeom = new THREE.BoxGeometry(strakeT, strakeH, strakeW);
          const posX = Math.cos(angle) * (pRadius + strakeT / 2);
          const posZ = Math.sin(angle) * (pRadius + strakeT / 2);
          const posY = yBodyStart + bodyLen * 0.4;

          strakeGeom.rotateY(-angle);
          strakeGeom.translate(posX, posY, posZ);
          geometries.push(strakeGeom);
        }

        return mergeGeometriesSimple(geometries);
      }

      function setupProjectile() {
        let pRadius = currentData.proj_diameter / 2.0;
        const projGeom = createGBU57Geometry(pRadius, currentData.proj_length);
        // Premium material - Glowing Projectile
        const projMat = new THREE.MeshPhysicalMaterial({
          color: 0x00ffff,
          metalness: 0.3,
          roughness: 0.2,
          clearcoat: 0.8,
          clearcoatRoughness: 0.1,
          emissive: 0x00ffff,
          emissiveIntensity: 10.0,
        });
        projectile = new THREE.Mesh(projGeom, projMat);
        projectile.castShadow = true;
        projectile.receiveShadow = true;
        scene.add(projectile);
      }

      function setupEffects() {
        const shockGeom = new THREE.SphereGeometry(4.0, 32, 32);
        const shockMat = new THREE.MeshBasicMaterial({
          color: 0xef4444,
          transparent: true,
          opacity: 0.6,
          wireframe: true,
        });
        shockwave = new THREE.Mesh(shockGeom, shockMat);
        shockwave.visible = false;
        scene.add(shockwave);

        const expGeom = new THREE.SphereGeometry(5.0, 32, 32);
        const expMat = new THREE.MeshPhysicalMaterial({
          color: 0xf97316,
          emissive: 0xf97316,
          emissiveIntensity: 2.0,
          transparent: true,
          opacity: 0.9,
        });
        explosionSphere = new THREE.Mesh(expGeom, expMat);
        explosionSphere.visible = false;
        scene.add(explosionSphere);

        // Refractive sonic boom
        const ringGeom = new THREE.RingGeometry(1, 2.5, 64);
        const ringMat = new THREE.MeshBasicMaterial({
          color: 0xa5f3fc,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.9,
        });
        boomRing = new THREE.Mesh(ringGeom, ringMat);
        boomRing.rotation.x = Math.PI / 2;
        boomRing.visible = false;
        scene.add(boomRing);

        // Volumetric Prandtl-Glauert Supersonic Mach Vapor Cone
        const machConeGroup = new THREE.Group();

        // 1. Core High-Pressure Compression Cone (Vertex gradient: High opacity at tip, fading at base)
        const coneGeom = new THREE.ConeGeometry(3.5, 12.0, 32, 16, true);
        const posAttr = coneGeom.attributes.position;
        const colors = [];
        const baseVaporColor = new THREE.Color(0x38bdf8); // Atmospheric cyan-blue vapor
        const tipIntenseColor = new THREE.Color(0xf0f9ff); // Bright shock compression tip

        for (let i = 0; i < posAttr.count; i++) {
          const y = posAttr.getY(i);
          // t = 1 at tip (y = +6), t = 0 at base (y = -6)
          const t = Math.max(0, Math.min(1, (y - -6.0) / 12.0));
          const c = new THREE.Color().lerpColors(
            baseVaporColor,
            tipIntenseColor,
            Math.pow(t, 2.0),
          );
          // Multiply RGB by t^1.5 so alpha/brightness vanishes towards base
          const intensity = Math.pow(t, 1.5);
          colors.push(c.r * intensity, c.g * intensity, c.b * intensity);
        }
        coneGeom.setAttribute(
          "color",
          new THREE.Float32BufferAttribute(colors, 3),
        );

        const coneMat = new THREE.MeshBasicMaterial({
          vertexColors: true,
          transparent: true,
          opacity: 0.32,
          side: THREE.DoubleSide,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        });
        const innerCone = new THREE.Mesh(coneGeom, coneMat);
        innerCone.rotation.x = Math.PI; // point down towards projectile nose
        machConeGroup.add(innerCone);

        // 2. Outer Soft Vapor Condensation Envelope
        const outerGeom = new THREE.ConeGeometry(4.8, 14.0, 32, 1, true);
        const outerMat = new THREE.MeshBasicMaterial({
          color: 0x0284c7,
          transparent: true,
          opacity: 0.08,
          side: THREE.DoubleSide,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        });
        const outerCone = new THREE.Mesh(outerGeom, outerMat);
        outerCone.rotation.x = Math.PI;
        machConeGroup.add(outerCone);

        // 3. Supersonic Condensation Dust / Vapor Swarm Particles
        const machDustGeo = new THREE.BufferGeometry();
        const machDustCount = 350;
        const machDustPos = new Float32Array(machDustCount * 3);
        for (let i = 0; i < machDustCount; i++) {
          const angle = Math.random() * Math.PI * 2;
          const h = Math.random(); // 0 at tip to 1 at base
          const r = h * 4.2 * Math.random();
          machDustPos[i * 3] = Math.cos(angle) * r;
          machDustPos[i * 3 + 1] = -6.0 + h * 12.0; // extending UPWARDS from apex (-6) to base (+6)
          machDustPos[i * 3 + 2] = Math.sin(angle) * r;
        }
        machDustGeo.setAttribute(
          "position",
          new THREE.BufferAttribute(machDustPos, 3),
        );
        const machDustMat = new THREE.PointsMaterial({
          color: 0x7dd3fc,
          size: 0.5,
          transparent: true,
          opacity: 0.3,
          blending: THREE.AdditiveBlending,
        });
        const machDust = new THREE.Points(machDustGeo, machDustMat);
        machConeGroup.add(machDust);

        machCone = machConeGroup;
        machCone.visible = false;
        scene.add(machCone);

        // Volumetric dust particles (InstancedMesh for high performance)
        const dustGeom = new THREE.DodecahedronGeometry(0.3, 0);
        const dustMat = new THREE.MeshStandardMaterial({
          color: 0x888888,
          roughness: 0.9,
        });
        dustParticles = new THREE.InstancedMesh(dustGeom, dustMat, 1000);
        dustParticles.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

        const dummy = new THREE.Object3D();
        for (let i = 0; i < 1000; i++) {
          dummy.position.set(0, -9999, 0); // Hide initially
          dummy.updateMatrix();
          dustParticles.setMatrixAt(i, dummy.matrix);
        }
        dustParticles.instanceMatrix.needsUpdate = true;
        scene.add(dustParticles);
      }

      function toggleFollowCam() {
        followCam = !followCam;
        const btn = document.getElementById("btn-follow");
        btn.innerText = followCam ? "Follow Cam: ON" : "Follow Cam: OFF";
        btn.className = followCam
          ? "px-2 py-2 rounded bg-emerald-900/80 hover:bg-emerald-500 hover:text-black font-semibold text-xs border border-emerald-500 transition"
          : "px-2 py-2 rounded bg-slate-800/80 hover:bg-cyan-500 hover:text-black font-semibold text-xs border border-slate-600 transition";
      }

      function setSimSpeed(speed) {
        simSpeedMultiplier = speed;
      }

      function smoothCameraMove(px, py, pz, tx, ty, tz) {
        controls.enableDamping = false; // Prevent fighting during tween
        new TWEEN.Tween(camera.position)
          .to({ x: px, y: py, z: pz }, 1000)
          .easing(TWEEN.Easing.Cubic.InOut)
          .start();

        new TWEEN.Tween(controls.target)
          .to({ x: tx, y: ty, z: tz }, 1000)
          .easing(TWEEN.Easing.Cubic.InOut)
          .onComplete(() => {
            controls.enableDamping = true;
          })
          .start();
      }

      function initECharts() {
        if (!echarts) return;
        telemetryChart = echarts.init(
          document.getElementById("telemetry-chart"),
        );

        const option = {
          backgroundColor: "transparent",
          tooltip: { trigger: "axis" },
          grid: { left: 5, right: 5, top: 10, bottom: 5, containLabel: false },
          xAxis: {
            type: "category",
            show: false,
            data: chartDataTime,
          },
          yAxis: {
            type: "value",
            show: false,
            min: 0,
          },
          series: [
            {
              name: "Velocity",
              type: "line",
              smooth: true,
              symbol: "none",
              itemStyle: { color: "#38bdf8" },
              areaStyle: {
                color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
                  { offset: 0, color: "rgba(56, 189, 248, 0.5)" },
                  { offset: 1, color: "rgba(56, 189, 248, 0.0)" },
                ]),
              },
              data: chartDataVel,
            },
          ],
        };
        telemetryChart.setOption(option);
      }

      function updateChart() {
        if (!telemetryChart) return;
        telemetryChart.setOption({
          xAxis: { data: chartDataTime },
          series: [{ data: chartDataVel }],
        });
      }

      function tweenNumber(elId, newVal, formatFn) {
        const el = document.getElementById(elId);
        const oldVal = parseFloat(el.getAttribute("data-val") || 0);
        new TWEEN.Tween({ val: oldVal })
          .to({ val: newVal }, 100)
          .onUpdate(function (obj) {
            el.innerText = formatFn(obj.val);
            el.setAttribute("data-val", obj.val);
          })
          .start();
      }

      function updateHUD(frame) {
        tweenNumber("hud-velocity", frame.v, (v) => v.toFixed(1) + " m/s");

        if (frame.p !== undefined) {
          tweenNumber("hud-pressure", frame.p, (p) => p.toFixed(2) + " GPa");
          const yieldLim = currentData.yield || 2.0; // fallback
          const pPct = Math.min(100, (frame.p / yieldLim) * 100);
          document.getElementById("bar-pressure").style.width = pPct + "%";

          if (frame.p > yieldLim)
            document.getElementById("bar-pressure").className =
              "bg-rose-500 h-full progress-bar";
          else if (pPct > 80)
            document.getElementById("bar-pressure").className =
              "bg-amber-400 h-full progress-bar";
          else
            document.getElementById("bar-pressure").className =
              "bg-cyan-400 h-full progress-bar";
        }

        tweenNumber("hud-depth", Math.abs(frame.y), (y) => y.toFixed(2) + " m");
        document.getElementById("hud-depth-label").innerText =
          animState === "DROPPING" ? "ALTITUDE" : "PENETRATION DEPTH";

        if (animState === "PENETRATING") {
          tweenNumber("hud-gforce", frame.g ?? 0, (g) => g.toFixed(0) + " G");

          // Thermal heat glow mapping is handled in the main render loop for the 3D mesh
        }

        // CEB-FIP DIF / WAPM erosion phase telemetry (penetration-phase only)
        if (frame.dif !== undefined) {
          tweenNumber("hud-dif", frame.dif, (d) => d.toFixed(2) + "x");
        }
        if (frame.rl !== undefined) {
          tweenNumber("hud-length", frame.rl, (l) => l.toFixed(2) + " m");
        }
        if (frame.e !== undefined) {
          const phaseEl = document.getElementById("hud-phase");
          phaseEl.innerText = frame.e ? "ERODING (WAPM)" : "RIGID";
          phaseEl.className = frame.e
            ? "text-purple-300 font-bold text-sm"
            : "text-cyan-300 font-bold text-sm";
        }

        // Update ECharts
        chartDataTime.push(frame.t !== undefined ? frame.t.toFixed(2) : "");
        chartDataVel.push(frame.v);

        if (chartDataTime.length > 100) {
          chartDataTime.shift();
          chartDataVel.shift();
        }

        // Throttle chart updates slightly to prevent layout thrashing on fast sims
        if (Math.random() > 0.5) {
          updateChart();
        }
      }

      function buildFinalBadges(data) {
        const regimeBadge = document.getElementById("hud-regime-badge");
        const expBadge = document.getElementById("hud-exp-badge");
        document.getElementById("hud-scenario").innerText = data.name;

        // --- INJECT ALL DATA INTO STATISTICS PANEL ---
        for (const key in data) {
          if (
            key === "drop_frames" ||
            key === "pen_frames" ||
            key === "target_layers"
          )
            continue;

          let val = data[key];
          if (typeof val === "number") {
            val = val % 1 === 0 ? val.toString() : val.toFixed(4);
          }

          const el = document.getElementById("stat-" + key);
          if (el) {
            el.innerText = val;
          }
        }
        // ---------------------------------------------

        // Reset yield mark
        document.getElementById("bar-yield-mark").style.left = "100%"; // Assuming bar max is yield * 1.2

        // Walker-Wasley shock initiation telemetry (peak values, static per scenario)
        document.getElementById("hud-shock-pressure").innerText =
          (data.shock_pressure_gpa_peak || 0).toFixed(2) + " GPa";
        document.getElementById("hud-shock-ratio").innerText =
          Math.min(100, data.shock_prob || 0).toFixed(0) + "%";

        // Regime / outcome text straight from the C++ physics engine (previously computed but
        // never surfaced in the UI)
        document.getElementById("hud-regime-text").innerText =
          (data.regime || "-") +
          (data.summary ? " \u2014 " + data.summary : "");

        // Reset phase/DIF/rod-length displays for the newly selected scenario
        document.getElementById("hud-phase").innerText = data.is_kinetic
          ? "KINETIC APPROACH"
          : "RIGID";
        document.getElementById("hud-dif").innerText = "1.00x";
        document.getElementById("hud-length").innerText =
          (data.proj_length || 0).toFixed(2) + " m";

        if (data.is_kinetic) {
          regimeBadge.innerText = "HYPERVELOCITY KINETIC ROD";
          regimeBadge.className =
            "px-3 py-2 rounded text-center text-[11px] font-black tracking-widest uppercase bg-purple-500/20 text-purple-400 border border-purple-500/50 shadow-[0_0_15px_rgba(168,85,247,0.5)] pulse-active";
          expBadge.innerText = "PAYLOAD: ZERO EXPLOSIVE MASS";
          expBadge.className =
            "px-3 py-1.5 rounded text-center text-[10px] font-bold tracking-widest bg-slate-800/80 text-slate-300 border border-slate-700";

          // Swap geometry
          projectile.geometry.dispose();
          let pRadius = currentData.proj_diameter / 2.0;
          projectile.geometry = createGBU57Geometry(
            pRadius,
            currentData.proj_length,
          );
          projectile.material.metalness = 0.5;
          projectile.material.color.setHex(0xa855f7);
        } else if (data.fail || !data.exp_survives) {
          regimeBadge.innerText = data.fail ? "CASING SHATTER" : "FUZE FAILURE";
          regimeBadge.className =
            "px-3 py-2 rounded text-center text-[11px] font-black tracking-widest uppercase bg-rose-500/20 text-rose-400 border border-rose-500/50 shadow-[0_0_15px_rgba(244,63,94,0.5)] pulse-active";
          expBadge.innerText = data.fail
            ? "PAYLOAD DESTROYED"
            : "EXPLOSIVE CHARGE FAILED";
          expBadge.className =
            "px-3 py-1.5 rounded text-center text-[10px] font-bold tracking-widest bg-rose-950/60 text-rose-300 border border-rose-800/60";
        } else {
          regimeBadge.innerText = "RIGID DRILL PENETRATION";
          regimeBadge.className =
            "px-3 py-2 rounded text-center text-[11px] font-black tracking-widest uppercase bg-emerald-500/20 text-emerald-400 border border-emerald-500/50 shadow-[0_0_15px_rgba(16,185,129,0.5)] pulse-active";
          expBadge.innerText = "PAYLOAD SURVIVED";
          expBadge.className =
            "px-3 py-1.5 rounded text-center text-[10px] font-bold tracking-widest bg-emerald-950/60 text-emerald-300 border border-emerald-800/60";
        }
      }

      function clearGroup(group) {
        while (group.children.length > 0) {
          const child = group.children[0];
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material))
              child.material.forEach((m) => m.dispose());
            else child.material.dispose();
          }
          group.remove(child);
        }
      }

      function createCraterGeometry(depth) {
        const points = [];
        const r_wide = currentData ? currentData.crater_wide_radius : 4.5;
        const r_narrow = currentData ? currentData.crater_narrow_radius : 1.0;
        const shallow_depth = Math.min(depth, 3.5);

        // Spline smoothing could go here, for now linear interpolation points
        points.push(new THREE.Vector2(r_wide, 0.1));
        points.push(new THREE.Vector2(r_narrow, -shallow_depth));
        points.push(new THREE.Vector2(r_narrow, -depth));
        points.push(new THREE.Vector2(0, -depth));
        return new THREE.LatheGeometry(points, 64);
      }

      function selectScenario(index, manualClick = true) {
        if (!scenarios[index]) return;
        TWEEN.removeAll(); // Clear running UI/Camera animations
        stopAnthem(); // Stop any running national anthem sound

        currentData = scenarios[index];
        document.querySelectorAll(".scenario-btn").forEach((btn, i) => {
          if (i === index) {
            btn.className =
              "scenario-btn px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all duration-200 bg-cyan-500 text-slate-950 shadow-[0_0_15px_rgba(6,182,212,0.6)] scale-105";
          } else {
            btn.className =
              "scenario-btn px-4 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap transition-all duration-200 bg-slate-800/80 hover:bg-cyan-500/20 hover:text-cyan-300 text-slate-300 border border-slate-700/60";
          }
        });

        let maxAlt = 0;
        if (currentData.drop_frames && currentData.drop_frames.length > 0) {
          maxAlt = Math.abs(currentData.drop_frames[0].y);
        }

        // Always clear and rebuild, properly disposing of memory
        clearGroup(targetLayersGroup);
        clearGroup(cratersGroup);
        clearGroup(airGroup);

        // Build Air Volume and Dust Particles
        let effectiveAlt = maxAlt > 0 ? maxAlt : 60;
        const airGeo = new THREE.BoxGeometry(100, effectiveAlt, 100);
        const airMat = new THREE.MeshPhysicalMaterial({
          color: 0x0284c7,
          transparent: true,
          opacity: 0.05,
          transmission: 0.9,
          roughness: 0.1,
          depthWrite: false,
          side: THREE.DoubleSide,
        });
        airBox = new THREE.Mesh(airGeo, airMat);
        airBox.position.y = effectiveAlt / 2;
        airGroup.add(airBox);

        // Dust particles (falling flakes with barometric altitude density gradient)
        const maxH = effectiveAlt + 30;
        const scaleK = 2.2 / maxH;
        const sampleAltitude = () => {
          const u = Math.random();
          return -Math.log(1 - u * (1 - Math.exp(-2.2))) / scaleK;
        };

        const dustGeo = new THREE.BufferGeometry();
        const dustVerts = [];
        for (let i = 0; i < 2500; i++) {
          dustVerts.push(
            (Math.random() - 0.5) * 150,
            sampleAltitude(),
            (Math.random() - 0.5) * 150,
          );
        }
        dustGeo.setAttribute(
          "position",
          new THREE.Float32BufferAttribute(dustVerts, 3),
        );
        const dustMat = new THREE.PointsMaterial({
          color: 0xbae6fd,
          size: 0.8,
          transparent: true,
          opacity: 0.6,
        });
        ambientDustParticles = new THREE.Points(dustGeo, dustMat);
        airGroup.add(ambientDustParticles);

        let currentY = 0;
        if (currentData.target_layers && currentData.target_layers.length > 0) {
          currentData.target_layers.forEach((layer) => {
            const thickness = Math.max(2, Math.min(60, layer.thickness));
            const blockGeom = new THREE.BoxGeometry(32, thickness - 0.05, 32); // 0.05 gap

            let color = 0x334155;
            let rough = 0.8;
            let metal = 0.1;
            if (layer.density < 2000) {
              color = 0x5c4033;
              rough = 1.0;
              metal = 0.0;
            } // Dirt
            else if (layer.density > 2600) {
              color = 0x1e293b;
              rough = 0.4;
              metal = 0.3;
            } // Hard rock/concrete

            const blockMat = new THREE.MeshStandardMaterial({
              color: color,
              transparent: true,
              opacity: 0.6,
              roughness: rough,
              metalness: metal,
              depthWrite: false,
            });
            const blockMesh = new THREE.Mesh(blockGeom, blockMat);
            blockMesh.position.set(0, currentY - thickness / 2, 0);
            blockMesh.receiveShadow = true;

            const edges = new THREE.EdgesGeometry(blockGeom);
            const line = new THREE.LineSegments(
              edges,
              new THREE.LineBasicMaterial({
                color: 0x475569,
                linewidth: 1.0,
                transparent: true,
                opacity: 0.4,
              }),
            );
            blockMesh.add(line);

            targetLayersGroup.add(blockMesh);
            currentY -= thickness;
          });
        }

        rebuildRulers(maxAlt);

        // Reset graph
        chartDataTime = [];
        chartDataVel = [];
        updateChart();

        // Red glowing hole/tunnel as requested by user
        const craterMat = new THREE.MeshStandardMaterial({
          color: 0xef4444,
          emissive: 0xb91c1c,
          emissiveIntensity: 2.5,
          roughness: 0.4,
          metalness: 0.2,
          side: THREE.DoubleSide,
        });
        activeCrater = new THREE.Mesh(createCraterGeometry(0.1), craterMat);
        activeCrater.visible = false;
        cratersGroup.add(activeCrater);

        // Reset Projectile Geometry
        if (!currentData.is_kinetic) {
          projectile.geometry.dispose();
          let pRadius = currentData.proj_diameter / 2.0;
          projectile.geometry = createGBU57Geometry(
            pRadius,
            currentData.proj_length,
          );
          projectile.material.metalness = 0.3;
          projectile.material.color.setHex(0x00ffff);
          projectile.material.emissive.setHex(0x00ffff);
          projectile.material.emissiveIntensity = 10.0;
        } else {
          projectile.material.emissive.setHex(0x9333ea); // Purple glow for kinetic
          projectile.material.emissiveIntensity = 10.0;
        }
        projectile.scale.set(1, 1, 1);
        projectile.position.set(0, maxAlt > 0 ? maxAlt : 50, 0);
        // Aircraft release: start 100% horizontal (pitched 90 degrees / PI / 2), exactly like B-2 drop
        projectile.rotation.set(0, 0, Math.PI / 2.0);
        projectile.visible = true;

        // Reset Effect States fully
        machCone.visible = false;
        shockwave.visible = false;
        shockwave.scale.set(1, 1, 1);
        shockwave.material.opacity = 0.6;

        explosionSphere.visible = false;
        explosionSphere.scale.set(0.1, 0.1, 0.1);
        explosionSphere.material.opacity = 0.9;

        boomRing.visible = false;
        boomRing.scale.set(1, 1, 1);
        boomRing.material.opacity = 0.9;

        buildFinalBadges(currentData);

        animState = "PRE_DELAY";
        simTime = 0;
        prevFrame = null;
        explosionTriggered = false;
        cameraShake = 0;
      }

      function onWindowResize() {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
        composer.setSize(window.innerWidth, window.innerHeight);
      }

      function getInterpolatedFrame(frames, t) {
        if (frames.length === 0) return null;
        if (t <= frames[0].t) return frames[0];
        if (t >= frames[frames.length - 1].t) return frames[frames.length - 1];

        let idx = frames.findIndex((f) => f.t >= t);
        if (idx === 0) idx = 1;

        const f0 = frames[idx - 1];
        const f1 = frames[idx];
        const factor = (t - f0.t) / (f1.t - f0.t);

        return {
          t: t,
          y: THREE.MathUtils.lerp(f0.y, f1.y, factor),
          v: THREE.MathUtils.lerp(f0.v, f1.v, factor),
          m: THREE.MathUtils.lerp(f0.m, f1.m, factor),
          p:
            f0.p !== undefined
              ? THREE.MathUtils.lerp(f0.p, f1.p, factor)
              : undefined,
          g:
            f0.g !== undefined
              ? THREE.MathUtils.lerp(f0.g, f1.g, factor)
              : undefined,
          h:
            f0.h !== undefined
              ? THREE.MathUtils.lerp(f0.h, f1.h, factor)
              : undefined,
          dif:
            f0.dif !== undefined
              ? THREE.MathUtils.lerp(f0.dif, f1.dif, factor)
              : undefined,
          rl:
            f0.rl !== undefined
              ? THREE.MathUtils.lerp(f0.rl, f1.rl, factor)
              : undefined,
          ob:
            f0.ob !== undefined
              ? THREE.MathUtils.lerp(f0.ob, f1.ob, factor)
              : undefined,
          obliquity_deg:
            f0.obliquity_deg !== undefined
              ? THREE.MathUtils.lerp(f0.obliquity_deg, f1.obliquity_deg, factor)
              : f0.ob !== undefined
                ? THREE.MathUtils.lerp(f0.ob, f1.ob, factor)
                : undefined,
          aoa_deg:
            f0.aoa_deg !== undefined
              ? THREE.MathUtils.lerp(f0.aoa_deg, f1.aoa_deg, factor)
              : undefined,
          sb: factor < 0.5 ? f0.sb : f1.sb,
          e: factor < 0.5 ? f0.e : f1.e,
        };
      }

      function animate(time) {
        requestAnimationFrame(animate);
        TWEEN.update(time);

        let dt = clock.getDelta();
        if (dt > 0.1) dt = 0.1; // Cap delta to prevent huge jumps

        if (ambientDustParticles && airBox) {
          const positions =
            ambientDustParticles.geometry.attributes.position.array;
          const maxH = airBox.geometry.parameters.height + 30;
          const scaleK = 2.2 / maxH;

          for (let i = 1; i < positions.length; i += 3) {
            const y = positions[i];
            const airDensityFactor = Math.exp(-scaleK * y);
            // Slower terminal fall velocity near ground (dense air), faster fall at high altitude (thin air)
            const fallSpeed = 3.0 + 6.0 * (1.0 - airDensityFactor);

            positions[i] -= dt * fallSpeed;
            if (positions[i] < 0) {
              const u = Math.random();
              positions[i] = -Math.log(1 - u * (1 - Math.exp(-2.2))) / scaleK;
            }
          }
          ambientDustParticles.geometry.attributes.position.needsUpdate = true;
        }

        if (animState === "PRE_DELAY") {
          simTime += dt;
          if (simTime > 1.0) {
            animState =
              currentData.drop_frames && currentData.drop_frames.length > 0
                ? "DROPPING"
                : "PENETRATING";

            // Play USA National Anthem as bomb drop animation begins!
            playAnthem();

            if (animState === "DROPPING") {
              simTime = currentData.drop_frames[0].t;
            } else if (
              currentData.pen_frames &&
              currentData.pen_frames.length > 0
            ) {
              simTime = currentData.pen_frames[0].t;
            } else {
              simTime = 0;
            }
          }
        } else if (animState === "DROPPING") {
          simTime += dt * simSpeedMultiplier;
          const maxTime =
            currentData.drop_frames[currentData.drop_frames.length - 1].t;

          if (simTime < maxTime) {
            const frame = getInterpolatedFrame(
              currentData.drop_frames,
              simTime,
            );
            projectile.position.y = frame.y;

            // 100% Physically-based aerodynamic pitch alignment:
            // Fin-stabilized flight path angle of attack theta = atan2(vx, |vy|)
            const maxDropAlt =
              currentData &&
              currentData.drop_frames &&
              currentData.drop_frames.length > 0
                ? Math.abs(currentData.drop_frames[0].y)
                : 60;
            // Aerodynamic free-fall pitch rotation:
            // Spawns 100% horizontal (PI/2 = 90 deg) matching aircraft release,
            // then aerodynamically rotates pitch smoothly down to vertical (0 deg) as it accelerates toward ground
            const dropProgress = Math.max(
              0,
              Math.min(1.0, 1.0 - frame.y / maxDropAlt),
            );
            const pitchRad =
              frame.pr !== undefined
                ? frame.pr
                : (Math.PI / 2.0) * (1.0 - Math.pow(dropProgress, 0.75));
            projectile.rotation.z = pitchRad;

            if (frame.sb === true) {
              boomRing.visible = true;
              // boomRing.position.copy(projectile.position);

              // Match projectile pitch rotation angle
              boomRing.rotation.z = projectile.rotation.z;

              // Rotate offset vector around Z axis so Mach cone stays attached to nose tip as bomb rotates
              const offsetLen = currentData.proj_length / 2.0 - 1.8;
              boomRing.position.x =
                projectile.position.x -
                Math.sin(projectile.rotation.z) * offsetLen;
              boomRing.position.y =
                projectile.position.y +
                Math.cos(projectile.rotation.z) * offsetLen;

              boomRing.scale.set(1, 1, 1);
              boomRing.material.opacity = 1.0;
              // Faster/more energetic booms for higher Mach numbers (physics-derived rate)
              boomRingGrowthRate = 8.0 + Math.min(30.0, frame.m) * 1.2;
            }

            // 100% Physically-based Mach Cone Generation: Velocity + Aerodynamic Friction + Air Density
            if (frame.v > 343.0 && frame.m > 1.0) {
              machCone.visible = true;

              // Local atmospheric air density ratio (highest at ground level y=0, decaying exponentially with altitude)
              const scaleK = 2.2 / (maxDropAlt + 30);
              const airDensityFactor = Math.exp(-scaleK * Math.max(0, frame.y));

              // Velocity/Mach expansion factor (0 at Mach 1.0, max at Mach 1.7+)
              const velMachFactor = Math.min(1.0, (frame.m - 1.0) / 0.7);

              // Combined Physical Intensity: Dynamic Pressure & Air Friction (q = 1/2 * rho * v^2)
              const machIntensity =
                velMachFactor * (0.35 + 0.65 * airDensityFactor);

              if (machCone.children && machCone.children.length >= 3) {
                machCone.children[0].material.opacity = 0.35 * machIntensity;
                machCone.children[1].material.opacity = 0.08 * machIntensity;
                machCone.children[2].material.opacity = 0.3 * machIntensity;
              }

              // Match projectile pitch rotation angle
              machCone.rotation.z = projectile.rotation.z;

              // Rotate offset vector around Z axis so Mach cone stays attached to nose tip as bomb rotates
              const offsetLen = currentData.proj_length / 2.0 - 1.8;
              machCone.position.x =
                projectile.position.x -
                Math.sin(projectile.rotation.z) * offsetLen;
              machCone.position.y =
                projectile.position.y +
                Math.cos(projectile.rotation.z) * offsetLen;

              // Dynamically scale Mach cone angle (sin(alpha) = 1/M): higher Mach = narrower cone
              const machAngleFactor = Math.max(
                0.35,
                Math.min(1.2, 1.4 / Math.max(1.01, frame.m)),
              );
              machCone.scale.set(machAngleFactor, 1.0, machAngleFactor);
            } else {
              machCone.visible = false;
            }

            updateHUD(frame);
            prevFrame = frame;
          } else {
            animState = "PENETRATING";
            machCone.visible = false;

            // Trigger ground impact shockwave sphere (driven 100% by kinetic energy = 1/2 * m * v^2)
            // Kinetic shock energy is computed and exported from the C++ backend simulation engine
            const kineticShockJoules = currentData.kinetic_shock_joules || 0.0;

            // Energy scale factor for sphere radius and expansion rate
            const keScale = Math.max(
              1.0,
              Math.pow(kineticShockJoules / 1e8, 0.333),
            );

            shockwave.visible = false;

            if (currentData.pen_frames && currentData.pen_frames.length > 0) {
              simTime = currentData.pen_frames[0].t;
            } else {
              simTime = 0;
            }
            prevFrame = null;
            cameraShake = currentData.camera_shake_magnitude; // Physically derived camera shake
          }
        } else if (animState === "PENETRATING") {
          if (!currentData.pen_frames || currentData.pen_frames.length === 0) {
            animState = "EXPLODING";
            simTime = 0;
          } else {
            const penStart = currentData.pen_frames[0].t;
            const penEnd =
              currentData.pen_frames[currentData.pen_frames.length - 1].t;
            const penDuration = penEnd - penStart;
            // Force penetration animation to take at least 5.0 seconds of real time for visibility
            const overrideTimeScale = penDuration > 0 ? penDuration / 5.0 : 1.0;
            simTime += dt * overrideTimeScale * simSpeedMultiplier;

            const maxTime =
              currentData.pen_frames[currentData.pen_frames.length - 1].t;

            if (simTime < maxTime) {
              const frame = getInterpolatedFrame(
                currentData.pen_frames,
                simTime,
              );

              // 1. WAPM Erosion (Rod Shrinking)
              const currentLength =
                frame.rl !== undefined ? frame.rl : currentData.proj_length;
              projectile.scale.y = currentLength / currentData.proj_length;
              projectile.position.y = -frame.y + currentLength / 2.0;

              // 2. C++ Hydrocode Obliquity & Trajectory Bending Dynamics
              // Read exact C++ simulation obliquity/refraction angle (obliquity_deg or ob)
              const oblDeg =
                frame.obliquity_deg !== undefined
                  ? frame.obliquity_deg
                  : frame.ob || 0;
              const aoaDeg = frame.aoa_deg || 0;

              // Total orientation angle = C++ Obliquity Trajectory Bending + Angle of Attack
              const totalAngleRad = (oblDeg + aoaDeg) * (Math.PI / 180);

              projectile.rotation.z = totalAngleRad;
              activeCrater.rotation.z = totalAngleRad;

              // 3. Thermal Ablation & Friction Heat Planck Blackbody Radiation
              const tempVal = frame.h !== undefined ? frame.h : 20;
              // If temperature is reported in Celsius, convert to Kelvin
              const tempKelvin = tempVal < 200 ? tempVal + 273.15 : tempVal;
              const baseColorHex = currentData.is_kinetic ? 0xa855f7 : 0x00ffff;

              const thermoColor = computePlanckBlackbodyColor(
                tempKelvin,
                baseColorHex,
              );
              projectile.material.emissive.copy(thermoColor);

              // Stefan-Boltzmann Law emissive radiation intensity (scaling with T^4)
              const tempNorm = Math.max(0, (tempKelvin - 300) / 1500);
              projectile.material.emissiveIntensity =
                2.0 + Math.pow(tempNorm, 3.0) * 18.0;

              // 5. Shock Stress & G-Force Tremors
              const gForce = frame.g || 0;
              const jitter = gForce / 15000.0; // e.g. 15000G = 1.0 magnitude jitter
              projectile.position.x = (Math.random() - 0.5) * jitter;
              projectile.position.z = (Math.random() - 0.5) * jitter;

              if (
                (currentData.shock_damage_prob_percent || 0) > 50.0 &&
                Math.random() > 0.8
              ) {
                // Flicker the projectile to white briefly to show intense shock stress
                projectile.material.color.setHex(0xffffff);
              } else {
                projectile.material.color.setHex(baseColorHex);
              }

              activeCrater.visible = true;
              activeCrater.geometry.dispose();
              activeCrater.geometry = createCraterGeometry(Math.abs(frame.y));

              // Volumetric Dust Emission
              if (dustParticles) {
                const pPos = projectile.position;
                for (let i = 0; i < 20; i++) {
                  // spawn/move 20 particles per frame
                  const idx = Math.floor(Math.random() * 1000);
                  const dummy = new THREE.Object3D();
                  // Emit from around the projectile head
                  dummy.position.set(
                    pPos.x + (Math.random() - 0.5) * 4.0,
                    pPos.y - Math.random() * 2.0,
                    pPos.z + (Math.random() - 0.5) * 4.0,
                  );
                  const scale = Math.random() * 2.0 + 0.5;
                  dummy.scale.set(scale, scale, scale);
                  dummy.updateMatrix();
                  dustParticles.setMatrixAt(idx, dummy.matrix);
                }
                dustParticles.instanceMatrix.needsUpdate = true;
              }

              updateHUD(frame);
              prevFrame = frame;
            } else {
              animState = "PRE_EXPLOSION";
              simTime = 0;
            }
          }
        } else if (animState === "PRE_EXPLOSION") {
          simTime += dt;
          if (simTime > 1.0) {
            animState = "EXPLODING";
            simTime = 0;
          }
        } else if (animState === "EXPLODING") {
          simTime += dt;

          if (!explosionTriggered) {
            explosionTriggered = true;
            if (currentData.is_kinetic) {
              projectile.material.color.setHex(0xc084fc);
              projectile.material.emissive.setHex(0x581c87);
              activeCrater.material.color.setHex(0xa855f7);
              activeCrater.material.emissive.setHex(0x7e22ce);
            } else if (currentData.fail || !currentData.exp_survives) {
              projectile.scale.set(1.8, 0.4, 1.8);
              projectile.material.color.setHex(0xf87171);
              projectile.material.emissive.setHex(0x7f1d1d);
              activeCrater.material.color.setHex(0xef4444);
              activeCrater.material.emissive.setHex(0xb91c1c);
            } else {
              explosionSphere.visible = true;
              explosionSphere.position.copy(projectile.position);
              projectile.visible = false;

              // Detonation Temperature & Explosive Type Color Calibration:
              // PBXN-109 / Tritonal (~3000 K): Intense Fiery Orange/Yellow (0xff7700)
              // AFX-757 / High-Temp Aluminized (~4000 K+): White-Hot Blinding Incandescence (0xfffbeb)
              const expMass = currentData.exp_mass || 2400.0;
              const detTempK = currentData.detonation_temp_k || 3400.0;

              let expColor = new THREE.Color(0xf97316);
              if (detTempK > 3800) {
                expColor.setHex(0xfffbeb); // White hot high-temp aluminized payload
              } else if (detTempK > 3200) {
                expColor.setHex(0xfb923c); // Bright orange/yellow detonation flame
              } else {
                expColor.setHex(0xd97706); // Deep amber/red standard HE flame
              }

              explosionSphere.material.color.copy(expColor);
              explosionSphere.material.emissive.copy(expColor);
              explosionSphere.material.emissiveIntensity = 5.0;
            }
          }

          if (explosionSphere.visible) {
            // Explosive payload shockwave yield is computed and exported from the C++ backend simulation engine
            const totalExplosiveYield =
              currentData.total_explosive_yield || 0.0;

            // Scale the explosion based directly on the actual computed total yield
            const maxScale = Math.max(
              5.0,
              Math.min(50.0, totalExplosiveYield / 2.5e8),
            ); // Sourced directly from C++ yield/mass logic

            // Growth rate scaled by the target size itself, so larger explosions (more explosive
            // mass) don't take proportionally longer to reach full scale than smaller ones.
            const explosionGrowthRate = Math.max(4.0, maxScale * 1.25);
            explosionSphere.scale.addScalar(dt * explosionGrowthRate);
            if (explosionSphere.scale.x > maxScale) {
              explosionSphere.material.opacity -= dt * 2.0;
            }
            if (explosionSphere.material.opacity <= 0) {
              explosionSphere.visible = false;
              animState = "DONE";
              simTime = 0;
              stopAnthem(); // Stop anthem when animation completes
            }
          } else if (shockwave.visible) {
            // Growth rate scaled by the physically-derived camera shake magnitude (kinetic energy)
            const shockwaveGrowthRate =
              10.0 + currentData.camera_shake_magnitude * 10.0;
            shockwave.scale.addScalar(dt * shockwaveGrowthRate);
            shockwave.material.opacity -= dt * 1.0;
            if (simTime > 1.5) {
              shockwave.visible = false;
              animState = "DONE";
              simTime = 0;
              stopAnthem(); // Stop anthem when animation completes
            }
          } else {
            if (simTime > 1.0) {
              animState = "DONE";
              simTime = 0;
              stopAnthem(); // Stop anthem when animation completes
            }
          }
        } else if (animState === "DONE") {
          simTime += dt;
          if (simTime > 2.0) {
            animState = "FINISHED";
          }
        }

        if (boomRing.visible) {
          boomRing.scale.addScalar(dt * boomRingGrowthRate);
          boomRing.material.opacity -= dt * 1.5;
          if (boomRing.material.opacity <= 0) boomRing.visible = false;
        }

        if (shockwave.visible) {
          shockwave.rotation.y += dt * 2;
          shockwave.rotation.x += dt;
        }

        if (followCam) {
          const delta = new THREE.Vector3().subVectors(
            projectile.position,
            controls.target,
          );
          camera.position.add(delta);
          controls.target.copy(projectile.position);
        }

        controls.update();

        // Apply camera shake temporarily before rendering
        let shakeOffset = new THREE.Vector3();
        if (cameraShake > 0) {
          shakeOffset.set(
            (Math.random() - 0.5) * cameraShake * 6,
            (Math.random() - 0.5) * cameraShake * 6,
            0,
          );
          camera.position.add(shakeOffset);
          cameraShake -= dt * 1.5;
        }

        composer.render(); // Use composer instead of renderer for Bloom

        // Revert shake offset so it doesn't drift
        if (shakeOffset.x !== 0 || shakeOffset.y !== 0) {
          camera.position.sub(shakeOffset);
        }
      }

      window.onload = init;
    